// What a payment method is used for. One method can carry several usages.
//
// - `deposits` — Pay In deposits
// - `billing` — Billing
// - `withdrawals` — Withdrawals
// - `payOutFunding` — Pay Out funding and remittances
// - `refunds` — Refunds
// - `returns` — Returns
type PaymentMethodUsage string

const (
	PaymentMethodUsageDeposits      PaymentMethodUsage = "deposits"
	PaymentMethodUsageBilling       PaymentMethodUsage = "billing"
	PaymentMethodUsageWithdrawals   PaymentMethodUsage = "withdrawals"
	PaymentMethodUsagePayOutFunding PaymentMethodUsage = "payOutFunding"
	PaymentMethodUsageRefunds       PaymentMethodUsage = "refunds"
	PaymentMethodUsageReturns       PaymentMethodUsage = "returns"
)

func NewPaymentMethodUsageFromString(s string) (PaymentMethodUsage, error) {
	switch s {
	case "deposits":
		return PaymentMethodUsageDeposits, nil
	case "billing":
		return PaymentMethodUsageBilling, nil
	case "withdrawals":
		return PaymentMethodUsageWithdrawals, nil
	case "payOutFunding":
		return PaymentMethodUsagePayOutFunding, nil
	case "refunds":
		return PaymentMethodUsageRefunds, nil
	case "returns":
		return PaymentMethodUsageReturns, nil
	}
	var t PaymentMethodUsage
	return "", fmt.Errorf("%s is not a valid %T", s, t)
}

func (p PaymentMethodUsage) Ptr() *PaymentMethodUsage {
	return &p
}

